import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ProdavnicaService } from '../prodavnica.service';
import jwt_decode from 'jwt-decode';
import { Prodavnica } from '../models/prodavnica';
import { Artikal } from '../models/artikal';           // 👈 NOVO

@Component({
  selector: 'app-infoprodavci',
  templateUrl: './infoprodavci.component.html',
  styleUrls: ['./infoprodavci.component.css']
})
export class InfoprodavciComponent implements OnInit {

  profilnaSlika: string | null = null;
  coverImageUrl: string | null = null;

  storeForm: FormGroup;
  email: string = '';
  isEditingProfile: boolean = false;

  stats = {
    artikli: 0,
    porudzbine: 0,
    rating: 4.9
  };

  // 👇 NOVO: artikli prodavnice + indeks slike po kartici
  artikli: Artikal[] = [];
  cardImageIndex: { [artikalId: string]: number } = {};

  constructor(
    private fb: FormBuilder,
    private prodavnicaService: ProdavnicaService
  ) {
    this.storeForm = this.fb.group({
      ime: ['', Validators.required],
      adresa: ['', Validators.required],
      opis: [''],
      radnoVreme: ['', Validators.required],
      kontaktInfo: ['', Validators.required]
    });
  }

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken: any = jwt_decode(token);
      this.email = decodedToken.email;
      this.loadStoreData();
      this.loadStats();
    }
  }

  // Učitaj podatke o prodavnici
  loadStoreData() {
    this.prodavnicaService.dohvatiProdavnicu(this.email).subscribe(
      (prodavnica: Prodavnica & { artikli?: Artikal[] }) => {
        this.storeForm.patchValue({
          ime: prodavnica.ime,
          adresa: prodavnica.adresa,
          opis: prodavnica.opis,
          radnoVreme: prodavnica.radnoVreme,
          kontaktInfo: prodavnica.kontaktInfo
        });

        this.profilnaSlika = prodavnica.slika || null;

        // 👇 NOVO: ako backend vraća artikle, smesti ih u grid
        if (prodavnica.artikli) {
          this.artikli = prodavnica.artikli;
          this.stats.artikli = this.artikli.length; // možeš ovako da vežeš statistiku
        }
      }
    );
  }

  // Snimi profil
  onSubmit() {
    if (this.storeForm.valid) {
      const updatedData = this.storeForm.value;

      this.prodavnicaService.azuriraj(this.email, updatedData).subscribe(
        () => {
          console.log('Profil ažuriran');
          this.isEditingProfile = false;
        },
        () => alert('Greška pri ažuriranju podataka.')
      );
    }
  }

  onImageSelected(event: Event): void {
    const input = event.target as HTMLInputElement;

    if (input.files && input.files[0]) {
      const selectedFile = input.files[0];

      this.prodavnicaService.uploadProfileImage(this.email, selectedFile)
        .subscribe(
          (response) => {
            this.profilnaSlika = response.slika;
          },
          (error) => {
            console.error('Greška pri dodavanju profilne slike:', error);
          }
        );
    }
  }

  onCoverImageSelected(event: Event): void {
    const input = event.target as HTMLInputElement;

    if (input.files && input.files[0]) {
      const selectedFile = input.files[0];
      console.log('Cover slika izabrana:', selectedFile.name);
    }
  }

  getProdavnicaImage(): string {
    if (this.profilnaSlika) {
      return `http://localhost:4000/${this.profilnaSlika}`;
    }
    return 'assets/default-profile.png';
  }

  loadStats() {
    // ako hoćeš da ostane dummy – ovo može da ostane
    this.stats = {
      artikli: this.stats.artikli || 44,
      porudzbine: 268,
      rating: 4.9
    };
  }

  toggleEdit(): void {
    this.isEditingProfile = !this.isEditingProfile;

    if (this.isEditingProfile) {
      setTimeout(() => {
        const el = document.getElementById('profile-edit-inline');
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }, 0);
    }
  }

  // ====== 👇👇👇 NOVO: helper za slike u gridu ======

  private buildImageUrl(path: string | undefined): string {
    if (!path) return 'assets/no-image.png';
    return `http://localhost:4000/${path}`;
  }

  getCardImage(artikal: Artikal): string {
    const slike: any = (artikal as any).slike;
    if (!slike) return 'assets/no-image.png';

    let index = this.cardImageIndex[artikal._id] ?? 0;

    if (Array.isArray(slike) && slike.length > 0) {
      if (index >= slike.length) index = 0;
      return this.buildImageUrl(slike[index]);
    }

    return this.buildImageUrl(slike as string);
  }

  nextCardImage(artikal: Artikal, event: MouseEvent) {
    event.stopPropagation(); // da klik na strelicu ne radi nešto drugo (npr. routerLink)
    const slike: any = (artikal as any).slike;
    if (!Array.isArray(slike) || slike.length === 0) return;

    const current = this.cardImageIndex[artikal._id] ?? 0;
    this.cardImageIndex[artikal._id] = (current + 1) % slike.length;
  }

  prevCardImage(artikal: Artikal, event: MouseEvent) {
    event.stopPropagation();
    const slike: any = (artikal as any).slike;
    if (!Array.isArray(slike) || slike.length === 0) return;

    const current = this.cardImageIndex[artikal._id] ?? 0;
    this.cardImageIndex[artikal._id] =
      (current - 1 + slike.length) % slike.length;
  }
}
<div class="profile-page">
  <!-- Header kao Instagram profil -->
  <div class="profile-header">
    <!-- Levo: profilna -->
    <div class="profile-avatar">
      <div class="avatar-circle">
        <img
          *ngIf="profilnaSlika; else avatarPlaceholder"
          [src]="getProdavnicaImage()"
          alt="Profilna slika"
        />
        <ng-template #avatarPlaceholder>
          <div class="avatar-placeholder">SH</div>
        </ng-template>
      </div>

      <label for="profileImageInput" class="change-avatar-link">
        Promeni profilnu
      </label>
      <input
        type="file"
        id="profileImageInput"
        (change)="onImageSelected($event)"
        accept="image/*"
      />
    </div>

    <!-- Desno: ime, bio, statistika -->
    <div class="profile-info">
      <div class="profile-title-row">
        <h1 class="store-name">
          {{ storeForm.get('ime')?.value || 'Ime prodavnice' }}
        </h1>
        <button type="button" class="edit-profile-btn" (click)="toggleEdit()">
          Uredi profil
        </button>
      </div>

      <div class="profile-stats">
        <div class="stat">
          <span class="stat-number">{{ stats?.artikli || 0 }}</span>
          <span class="stat-label">artikala</span>
        </div>
        <div class="stat">
          <span class="stat-number">{{ stats?.porudzbine || 0 }}</span>
          <span class="stat-label">porudžbina</span>
        </div>
        <div class="stat">
          <span class="stat-number">{{ stats?.rating || '4.9' }}</span>
          <span class="stat-label">ocena</span>
        </div>
      </div>

      <p class="store-bio">
        {{
          storeForm.get('opis')?.value ||
            'Dodajte kratak opis prodavnice, stil, veličine i politiku slanja.'
        }}
      </p>



      <div class="profile-meta">
        <span *ngIf="storeForm.get('adresa')?.value">
          📍 {{ storeForm.get('adresa')?.value }}
        </span>
        <span *ngIf="storeForm.get('radnoVreme')?.value">
          🕒 {{ storeForm.get('radnoVreme')?.value }}
        </span>
        <span *ngIf="storeForm.get('kontaktInfo')?.value">
          ☎ {{ storeForm.get('kontaktInfo')?.value }}
        </span>
      </div>
    </div>
  </div>

  <!-- Inline forma za uređivanje profila (pojavljuje se na klik "Uredi profil") -->
  <div
    class="profile-edit-inline"
    id="profile-edit-inline"
    *ngIf="isEditingProfile"
  >
    <h2>Uredi podatke o prodavnici</h2>

    <form [formGroup]="storeForm" (ngSubmit)="onSubmit()">
      <div class="form-row">
        <div class="form-group">
          <label for="ime">Ime prodavnice</label>
          <input
            type="text"
            id="ime"
            formControlName="ime"
            placeholder="Unesite ime prodavnice"
          />
        </div>

        <div class="form-group">
          <label for="adresa">Adresa</label>
          <input
            type="text"
            id="adresa"
            formControlName="adresa"
            placeholder="Unesite adresu prodavnice"
          />
        </div>
      </div>

      <div class="form-group">
        <label for="opis">Opis (bio)</label>
        <textarea
          id="opis"
          formControlName="opis"
          placeholder="Kratak opis prodavnice, stil, veličine, politika slanja..."
        ></textarea>
      </div>

      <div class="form-row">
        <div class="form-group">
          <label for="radnoVreme">Radno vreme</label>
          <input
            type="text"
            id="radnoVreme"
            formControlName="radnoVreme"
            placeholder="npr. Pon–Pet 10–18h"
          />
        </div>

        <div class="form-group">
          <label for="kontaktInfo">Kontakt informacije</label>
          <input
            type="text"
            id="kontaktInfo"
            formControlName="kontaktInfo"
            placeholder="Telefon, Instagram @username..."
          />
        </div>
      </div>

      <div class="form-actions">
        <button type="submit" [disabled]="!storeForm.valid">
          Sačuvaj promene
        </button>
      </div>
    </form>
  </div>

  <!-- Tabs kao na Instagramu -->
  <div class="profile-tabs">
    <button class="tab active">Artikli</button>
    <button class="tab">O prodavnici</button>
    <button class="tab">Recenzije</button>
  </div>

   <!-- Glavni deo: grid artikala -->
  <div class="profile-main">
    <div class="profile-grid" *ngIf="artikli && artikli.length > 0; else noItems">

      <!-- Jedna kartica artikla -->
      <div
        class="profile-grid-item"
        *ngFor="let artikal of artikli"
        [routerLink]="['/artikal', artikal._id]"
      >
        <div class="grid-image-wrapper">
          <img
            [src]="getCardImage(artikal)"
            alt="Artikal slika"
            class="grid-image"
          />

          <!-- Strelice za više slika – pojavljuju se samo ako ima više od 1 slike -->
          <button
            class="grid-arrow left"
            *ngIf="artikal.slike && artikal.slike.length > 1"
            (click)="prevCardImage(artikal, $event)"
          >
            ‹
          </button>
          <button
            class="grid-arrow right"
            *ngIf="artikal.slike && artikal.slike.length > 1"
            (click)="nextCardImage(artikal, $event)"
          >
            ›
          </button>
        </div>

        <div class="grid-item-info">
          <!-- ako hoćeš i tip, dodaj ispod -->
          <!-- <span class="grid-item-type">{{ artikal.tip }}</span> -->
          <span class="grid-item-price">{{ artikal.cena }} din</span>
        </div>
      </div>
    </div>

    <ng-template #noItems>
      <div class="profile-grid no-items">
        Trenutno nemate nijedan artikal. Dodajte svoj prvi komad odeće! ✨
      </div>
    </ng-template>
  </div>
</div>
